-- 세트 235: 내 서버의 네트워크 직접 점검하기: ip, hostname, getent, /etc/hosts, ss, nc -z, curl
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_linux_network_check_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (235, 1, '루프백 인터페이스 주소 보기 (ip -br a)', '서버 안의 네트워크 점검은 "이 서버에 어떤 주소가 붙어 있나" 를 보는 것에서 시작합니다. 자기 자신을 가리키는 **루프백 인터페이스 `lo`** 한 줄을 **간단한 표 형태**(`-br`)로 `/tmp/lo.txt` 에 저장하세요. (한 줄)', '`ip addr` 는 길게, `ip -br addr` 는 인터페이스마다 한 줄로 보여 줍니다. 인터페이스 이름을 `show` 뒤에 붙이면 그 하나만 나옵니다.', 'ip -br addr show lo > /tmp/lo.txt
cat /tmp/lo.txt

# 이름 / 상태 / 주소 순서. 전체를 보려면 ip -br a', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lo.txt)\\" -eq 1 ] && grep -q \\"^lo \\" /tmp/lo.txt ) && ( grep -q \\"127.0.0.1/8\\" /tmp/lo.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "한 줄이고 lo 로 시작한다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lo.txt)\\" -eq 1 ] && grep -q \\"^lo \\" /tmp/lo.txt"]}, {"label": "루프백 주소 127.0.0.1/8 이 들어 있다", "cmd": ["sh", "-c", "grep -q \\"127.0.0.1/8\\" /tmp/lo.txt"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 2, '이 서버의 호스트 이름 저장하기 (hostname)', '네트워크에서 이 서버가 스스로 부르는 이름이 **호스트 이름**입니다. 지금 서버의 호스트 이름을 `/tmp/myname.txt` 에 저장하세요.', '인자 없이 `hostname` 만 치면 현재 이름이 한 줄로 나옵니다. 눈으로 읽어 적지 말고 결과를 `>` 로 파일에 보내세요.', 'hostname > /tmp/myname.txt
cat /tmp/myname.txt

# 컨테이너에서는 보통 컨테이너 ID 앞부분이 이름이 된다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/myname.txt)\\" = \\"$(hostname)\\" ] ) && ( [ -s /tmp/myname.txt ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 hostname 출력과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/myname.txt)\\" = \\"$(hostname)\\" ]"]}, {"label": "비어 있지 않다", "cmd": ["sh", "-c", "[ -s /tmp/myname.txt ]"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 3, '127.0.0.1 로 가는 길목 찾기 (ip route get)', '패킷이 목적지로 갈 때 **어느 인터페이스를 거치는지**는 `ip route` 로 알 수 있습니다. 목적지 `127.0.0.1` 로 갈 때 쓰이는 **인터페이스 이름만** `/tmp/dev.txt` 에 저장하세요. (한 줄)', '`ip route get 목적지` 는 그 목적지에 쓰이는 경로를 한 줄로 알려 줍니다. 출력에서 `dev` 다음 단어가 인터페이스 이름입니다. `awk` 로 뽑거나 `grep -o` 를 써도 됩니다.', 'ip route get 127.0.0.1 | awk ''{for(i=1;i<=NF;i++) if($i=="dev") print $(i+1)}'' > /tmp/dev.txt
cat /tmp/dev.txt

# 출력: local 127.0.0.1 dev lo src 127.0.0.1 ... 꼴이라 dev 뒤 단어를 뽑는다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/dev.txt)\\" -eq 1 ] ) && ( [ \\"$(cat /tmp/dev.txt)\\" = \\"$(ip route get 127.0.0.1 | awk ''{for(i=1;i<=NF;i++) if($i==\\"dev\\") print $(i+1)}'')\\" ] && [ -n \\"$(cat /tmp/dev.txt)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "한 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/dev.txt)\\" -eq 1 ]"]}, {"label": "경로에 쓰이는 인터페이스 이름과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/dev.txt)\\" = \\"$(ip route get 127.0.0.1 | awk ''{for(i=1;i<=NF;i++) if($i==\\"dev\\") print $(i+1)}'')\\" ] && [ -n \\"$(cat /tmp/dev.txt)\\" ]"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 4, '이름이 가리키는 IP 풀어 보기 (getent hosts)', '이 서버의 `/etc/hosts` 에는 `api.example.test` 라는 이름이 등록되어 있습니다. 시스템이 이름을 실제로 어떻게 풀이하는지 `getent hosts` 로 물어서, **IP 주소만** `/tmp/api_ip.txt` 에 저장하세요. (한 줄)', '`getent hosts 이름` 은 `IP 이름` 꼴로 한 줄을 돌려줍니다. 첫 칸이 IP 라서 `awk ''{print $1}''` 또는 `cut -d'' '' -f1` 로 뽑을 수 있습니다. `/etc/hosts` 를 직접 읽어 적기보다 시스템에 물어보세요.', 'getent hosts api.example.test | awk ''{print $1}'' > /tmp/api_ip.txt
cat /tmp/api_ip.txt

# getent 는 /etc/hosts 와 DNS 를 시스템 설정 순서대로 따라간다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/api_ip.txt)\\" = \\"$(getent hosts api.example.test | awk ''{print $1}'')\\" ] && [ -n \\"$(cat /tmp/api_ip.txt)\\" ] ) && ( [ \\"$(wc -l < /tmp/api_ip.txt)\\" -eq 1 ] && grep -Eq \\"^[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\\.[0-9]+$\\" /tmp/api_ip.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "풀이된 IP 와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/api_ip.txt)\\" = \\"$(getent hosts api.example.test | awk ''{print $1}'')\\" ] && [ -n \\"$(cat /tmp/api_ip.txt)\\" ]"]}, {"label": "한 줄이고 IP 모양이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/api_ip.txt)\\" -eq 1 ] && grep -Eq \\"^[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\\.[0-9]+$\\" /tmp/api_ip.txt"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 5, '포트가 열렸는지 연결만 해 보기', '`nc` 로 `127.0.0.1` 의 `9090` 포트에 **데이터를 보내지 않고 연결만 시도**해서 열려 있는지 확인하려고 합니다. 빈칸에 알맞은 옵션을 채우세요.', '`nc` 는 접속도 하고 서버처럼 기다리기도 합니다. `nc -h` 로 옵션 설명을 읽어 "스캔만 한다(zero-I/O)" 는 뜻을 찾아보세요.', NULL, NULL, '[]', 'fill', '["-z", "-l", "-k", "-p"]', NULL, '`nc -z` 는 zero-I/O 모드로, 연결이 되는지만 확인하고 곧바로 끊습니다. `-l` 은 연결을 기다리는 서버 쪽이 되는 옵션이라 확인이 아니라 포트를 여는 일이고, `-k` 는 `-l` 과 함께 연결이 끝나도 계속 기다리게 하며, `-p` 는 내 쪽 출발 포트를 정하는 옵션입니다.', '[0]', 'nc {0} 127.0.0.1 9090', NULL, '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 6, 'DNS 서버 주소 읽기 (/etc/resolv.conf)', '이름을 IP 로 바꿀 때 물어볼 DNS 서버는 `/etc/resolv.conf` 의 `nameserver` 줄에 적혀 있습니다. **첫 번째 `nameserver` 의 주소만** `/tmp/ns.txt` 에 저장하세요. (한 줄)', '`grep ^nameserver /etc/resolv.conf` 로 줄을 찾고, 두 번째 칸이 주소입니다. 줄이 여러 개면 첫 줄만 써야 하니 `head -1` 이나 awk 의 `exit` 을 활용하세요. 주소는 환경마다 다르니 직접 읽어 적지 말고 명령 결과를 보내세요.', 'awk ''/^nameserver/{print $2; exit}'' /etc/resolv.conf > /tmp/ns.txt
cat /tmp/ns.txt

# grep ^nameserver /etc/resolv.conf | head -1 | awk ''{print $2}'' 도 같다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ -s /tmp/ns.txt ] && [ \\"$(wc -l < /tmp/ns.txt)\\" -eq 1 ] ) && ( [ \\"$(cat /tmp/ns.txt)\\" = \\"$(awk ''/^nameserver/{print $2; exit}'' /etc/resolv.conf)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "한 줄이고 비어 있지 않다", "cmd": ["sh", "-c", "[ -s /tmp/ns.txt ] && [ \\"$(wc -l < /tmp/ns.txt)\\" -eq 1 ]"]}, {"label": "첫 nameserver 주소와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ns.txt)\\" = \\"$(awk ''/^nameserver/{print $2; exit}'' /etc/resolv.conf)\\" ]"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 7, 'Could not resolve host 는 무슨 뜻일까', '`curl http://db.example.test:9090/` 를 실행했더니 `curl: (6) Could not resolve host: db.example.test` 가 나왔습니다. 가장 알맞은 해석을 고르세요.', '오류 문장의 동사 "resolve" 에 주목하세요. 이름을 무엇으로 바꾸는 일일까요? 서버에 연결을 시도하기 **전** 단계인지 **후** 단계인지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["이름을 IP 주소로 바꾸는 단계에서 실패했다. `/etc/hosts` 나 DNS 설정에 그 이름이 없다", "이름은 IP 로 풀렸지만 9090 포트에서 기다리는 프로그램이 없어 연결이 거부됐다", "서버가 응답하긴 했지만 HTTP 상태 코드가 5xx 였다", "연결은 됐지만 서버가 너무 늦게 응답해 시간이 초과됐다"]', 0, '`resolve` 는 이름을 IP 로 바꾸는 이름 풀이입니다. 이 오류는 연결을 시도하기도 전에, 이름에 해당하는 IP 를 찾지 못했다는 뜻이라 `/etc/hosts` 와 `/etc/resolv.conf`(DNS)를 살펴야 합니다. 포트에 아무도 없어 거부되는 경우는 이름이 풀린 뒤의 `Connection refused`(curl 종료 코드 7)이고, 5xx 는 서버가 응답한 뒤의 상태 코드이며, 시간 초과는 연결 시도 중 응답이 없을 때입니다.', NULL, NULL, NULL, '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 8, '이름을 127.0.0.1 로 연결하기 (/etc/hosts)', '`web.example.test` 라는 이름이 **이 서버 자신(`127.0.0.1`)** 을 가리키도록 `/etc/hosts` 에 등록하세요. 기존 줄(`localhost`, `api.example.test` 등)은 그대로 있어야 합니다.', '`/etc/hosts` 는 `IP 이름` 한 줄이 한 항목입니다. 파일 맨 끝에 줄을 **덧붙이는** 리다이렉션이 있습니다. (이 환경에서는 `sed -i` 로 파일을 통째로 바꾸려 하면 실패할 수 있습니다.) 다 한 뒤 `getent hosts web.example.test` 로 확인해 보세요.', 'echo ''127.0.0.1 web.example.test'' >> /etc/hosts
getent hosts web.example.test

# >> 는 덧붙이기, > 는 통째로 덮어쓰기라 기존 줄이 모두 사라진다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(getent hosts web.example.test | awk ''{print $1}'')\\" = 127.0.0.1 ] ) && ( grep -q \\"localhost\\" /etc/hosts && [ \\"$(getent hosts localhost | awk ''{print $1}'' | head -1)\\" != \\"\\" ] ) && ( [ \\"$(getent hosts api.example.test | awk ''{print $1}'')\\" = 192.0.2.20 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web.example.test 가 127.0.0.1 로 풀린다", "cmd": ["sh", "-c", "[ \\"$(getent hosts web.example.test | awk ''{print $1}'')\\" = 127.0.0.1 ]"]}, {"label": "기존 localhost 줄이 남아 있다", "cmd": ["sh", "-c", "grep -q \\"localhost\\" /etc/hosts && [ \\"$(getent hosts localhost | awk ''{print $1}'' | head -1)\\" != \\"\\" ]"]}, {"label": "api.example.test 도 그대로 풀린다", "cmd": ["sh", "-c", "[ \\"$(getent hosts api.example.test | awk ''{print $1}'')\\" = 192.0.2.20 ]"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 9, '포트를 직접 열고 확인하기 (nc -l, ss -ltn)', '`9090` 포트에서 연결을 기다리는 작은 서버를 **백그라운드로** 띄우세요. 터미널을 계속 쓸 수 있어야 하고, `ss -ltn` 으로 `9090` 이 LISTEN 중이라고 보여야 합니다.', '`nc -l -p 포트` 는 그 포트에서 연결을 기다립니다. 끝에 `&` 를 붙이면 백그라운드로 가고, `nohup` 을 앞에 붙이면 터미널 신호에 영향을 덜 받습니다. 띄운 뒤 `ss -ltn` 에서 `:9090` 을 찾아보세요. 확인한다고 `nc` 로 접속하면 대기 중이던 `nc` 가 끝나 버리니 주의하세요.', 'nohup nc -l -p 9090 >/dev/null 2>&1 &
sleep 1
ss -ltn | grep :9090

# nc -l 은 연결이 한 번 오면 끝난다. -k 를 붙이면 계속 기다린다(이미지의 nc 지원 시)', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( ss -ltn \\"sport = :9090\\" | grep -q LISTEN ) && ( pgrep -x nc > /dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "9090 이 LISTEN 중이다", "cmd": ["sh", "-c", "ss -ltn \\"sport = :9090\\" | grep -q LISTEN"]}, {"label": "연결을 기다리는 nc 프로세스가 있다", "cmd": ["sh", "-c", "pgrep -x nc > /dev/null"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 10, '연결이 거부될 때의 종료 코드 확인하기 (curl)', '`127.0.0.1` 의 `8099` 포트에는 기다리는 프로그램이 없습니다. 여기로 `curl` 을 보내 **연결이 거부된 뒤의 종료 코드**를 `/tmp/curl_rc.txt` 에 저장하세요. (숫자만)', '`curl -s http://127.0.0.1:8099/` 를 실행한 **바로 다음 줄**에 `echo $?` 를 쓰면 방금 명령의 종료 코드가 나옵니다. 그 출력을 파일로 보내세요.', 'curl -s http://127.0.0.1:8099/
echo $? > /tmp/curl_rc.txt
cat /tmp/curl_rc.txt

# curl 종료 코드 7 은 Failed to connect(연결 실패). 6 은 이름 풀이 실패다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/curl_rc.txt)\\" = 7 ] ) && ( ! ss -ltn | grep -q \\":8099 \\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "7 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/curl_rc.txt)\\" = 7 ]"]}, {"label": "8099 는 실제로 닫혀 있다", "cmd": ["sh", "-c", "! ss -ltn | grep -q \\":8099 \\""]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 11, '서버가 돌려준 HTTP 상태 코드 읽기 (curl -w)', '`127.0.0.1` 의 `8088` 포트에서 작은 웹 서버가 돌고 있습니다. 응답 본문은 버리고 **HTTP 상태 코드(숫자 3자리)만** `/tmp/code.txt` 에 저장하세요. (직접 짐작해서 적지 말고 서버에 물어보세요.)', '`curl -s -o /dev/null -w ''%{http_code}'' 주소` 는 본문을 버리고(`-o /dev/null`) 상태 코드만 출력(`-w`)합니다. 출력 끝에 줄바꿈이 없어도 괜찮습니다. 결과를 파일로 보내세요.', 'curl -s -o /dev/null -w ''%{http_code}'' http://127.0.0.1:8088/ > /tmp/code.txt
cat /tmp/code.txt

# 200 정상, 404 없음, 503 서비스 불가. -I 로 헤더 첫 줄을 봐도 된다', '["sh", "-c", "[ -f /tmp/.resp235.pid ] && kill $(cat /tmp/.resp235.pid) 2>/dev/null; pkill -x nc 2>/dev/null; sleep 0.3\\ngrep -v ''example.test'' /etc/hosts > /tmp/.hosts235; cat /tmp/.hosts235 > /etc/hosts; rm -f /tmp/.hosts235\\nrm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab\\necho ''192.0.2.20 api.example.test'' >> /etc/hosts\\ncat > /tmp/lab/resp503.sh <<''EOS''\\n#!/bin/bash\\nwhile true; do printf ''HTTP/1.1 503 Service Unavailable\\\\r\\\\nContent-Length: 0\\\\r\\\\nConnection: close\\\\r\\\\n\\\\r\\\\n'' | nc -l -p 8088 -q0 >/dev/null 2>&1; done\\nEOS\\nchmod +x /tmp/lab/resp503.sh\\nsetsid nohup /tmp/lab/resp503.sh >/dev/null 2>&1 </dev/null &\\necho $! > /tmp/.resp235.pid\\nsleep 0.5\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/code.txt)\\" = 503 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "서버가 준 상태 코드 503 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/code.txt)\\" = 503 ]"]}]', '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]'),
  (235, 12, '서버에 접속이 안 될 때 점검하는 순서', '`web.example.test` 에 접속이 안 됩니다. 아래 점검 단계를 **바깥에서 안쪽, 가까운 것에서 먼 것** 순서로 놓으세요. **앞에서 뒤**로 놓습니다.', '먼저 내 쪽 주소와 길이 정상이어야 하고, 그다음에 이름이 풀려야 하고, 목적지에서 포트가 열려 있어야 마지막으로 응답 내용을 볼 수 있습니다.', NULL, NULL, '[]', 'order', '["`ip -br a` 로 내 인터페이스에 주소가 붙어 있는지 본다", "`ip route` 로 목적지로 가는 경로가 있는지 본다", "`getent hosts web.example.test` 로 이름이 IP 로 풀리는지 본다", "`ss -ltn` 으로 서버 쪽 포트가 LISTEN 중인지 본다", "`curl -s -o /dev/null -w ''%{http_code}'' 주소` 로 실제 응답 코드를 본다"]', NULL, '**내 주소 → 경로 → 이름 풀이 → 포트 LISTEN → 응답 코드** 순서입니다. 주소와 경로가 없으면 이름 풀이도 연결도 의미가 없고, 이름이 풀려야 어느 서버에 물을지 알 수 있으며, 포트가 열려 있어야 HTTP 응답을 받을 수 있습니다. 응답 코드는 앞의 단계가 모두 통과한 뒤에야 의미 있는 정보를 줍니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "ip(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ip.8.html"}, {"title": "ss(8) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}, {"title": "hosts(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/hosts.5.html"}, {"title": "resolv.conf(5) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man5/resolv.conf.5.html"}]');
